-- m20261006_000043_onboarding: frozen on 11 November 2026 from the statements its sea-orm-migration `up` ran on PostgreSQL 18,
-- in order. Never edit it: `_sqlx_migrations` holds its checksum. A change is a new migration.
--
-- What the Rust migration said of itself:
--
-- Migration: **onboarding and offboarding**. `onboarding_templates` are custom checklist templates (a built-in one exists for each kind); `onboarding_cases` are one onboarding or offboarding of a person on a plan, or of a plan itself; `onboarding_items` are the checklist items of a case, each with an owner, a due date and a resolution; `access_records` are an **append-only** record of access granted and revoked (this service records it; it cannot change an identity provider's accounts).

CREATE TABLE IF NOT EXISTS "onboarding_templates" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "kind" varchar NOT NULL, "items" jsonb NOT NULL );

CREATE TABLE IF NOT EXISTS "onboarding_cases" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "kind" varchar NOT NULL, "plan_pid" uuid NOT NULL, "subject_ref" varchar NULL, "title" varchar NOT NULL, "effective_date" date NOT NULL, "status" varchar NOT NULL, "created_by" varchar NULL, "closed_at" timestamp with time zone NULL, "closed_reason" varchar NULL );

CREATE TABLE IF NOT EXISTS "onboarding_items" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "case_pid" uuid NOT NULL, "position" integer NOT NULL, "title" varchar NOT NULL, "owner_ref" varchar NULL, "due_date" date NULL, "resolution" varchar NULL, "note" varchar NULL, "resolved_at" timestamp with time zone NULL, "resolved_by" varchar NULL );

CREATE TABLE IF NOT EXISTS "access_records" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "plan_pid" uuid NOT NULL, "case_pid" uuid NULL, "person_ref" varchar NOT NULL, "access" varchar NOT NULL, "action" varchar NOT NULL, "recorded_on" date NOT NULL, "recorded_by" varchar NULL, "note" varchar NULL );

ALTER TABLE onboarding_templates ADD CONSTRAINT onboarding_templates_kind CHECK (kind IN ('person_join','person_leave','plan_intake','plan_closeout'));

CREATE UNIQUE INDEX onboarding_templates_kind_unique ON onboarding_templates (kind);

ALTER TABLE onboarding_cases ADD CONSTRAINT onboarding_cases_kind CHECK (kind IN ('person_join','person_leave','plan_intake','plan_closeout'));

ALTER TABLE onboarding_cases ADD CONSTRAINT onboarding_cases_status CHECK (status IN ('open','completed','cancelled'));

ALTER TABLE onboarding_cases ADD CONSTRAINT onboarding_cases_subject CHECK ((kind LIKE 'person_%') = (subject_ref IS NOT NULL));

CREATE INDEX onboarding_cases_plan ON onboarding_cases (plan_pid, status);

ALTER TABLE onboarding_items ADD CONSTRAINT onboarding_items_resolution CHECK (resolution IS NULL OR resolution IN ('done','skipped'));

CREATE INDEX onboarding_items_case ON onboarding_items (case_pid, position);

ALTER TABLE access_records ADD CONSTRAINT access_records_action CHECK (action IN ('granted','revoked'));

CREATE INDEX access_records_plan ON access_records (plan_pid, person_ref);

ALTER TABLE onboarding_templates ALTER COLUMN items TYPE json;
